(()=>{'use strict';const buttons=[...document.querySelectorAll('.go-lab [data-mode]')],title=document.getElementById('gl-mode-title'),copy=document.getElementById('gl-mode-copy'),data=document.getElementById('insurance-guide-data');const modes=data?JSON.parse(data.textContent):{"renew":["Имате полица? Нека я погледнем заедно.","Вземете настоящата полица и талона на автомобила. Ще уточним данните за собственика, кога изтича покритието и от коя дата ви е нужна новата застраховка."],"new":["Започваме с вашия автомобил.","Подгответе талона, данните за собственика и телефон за връзка. Кажете ни от коя дата ви трябва покритие. Ще ви помогнем да сравните предложенията."]};buttons.forEach(button=>button.addEventListener('click',()=>{buttons.forEach(b=>b.setAttribute('aria-pressed',String(b===button)));const content=modes[button.dataset.mode];title.textContent=content[0];copy.textContent=content[1]}));})();
